<?php $pageTitle='Monitoring Loket'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Petugas Registrasi','Petugas Rekam Medis','Administrator SIMRS','Manajemen']);$today=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE DATE(created_at)=CURDATE()")->fetchColumn();$waiting=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE DATE(created_at)=CURDATE() AND status IN ('Terdaftar','Menunggu','Dipanggil')")->fetchColumn();$completed=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE DATE(created_at)=CURDATE() AND status='Selesai'")->fetchColumn();$units=$pdo->query("SELECT mc.name,COUNT(v.id) total FROM master_clinics mc LEFT JOIN visits v ON v.clinic_id=mc.id AND DATE(v.created_at)=CURDATE() GROUP BY mc.id ORDER BY total DESC,mc.name")->fetchAll();$visits=$pdo->query("SELECT v.*,p.name,p.medical_record_no FROM visits v JOIN patients p ON p.id=v.patient_id WHERE DATE(v.created_at)=CURDATE() ORDER BY v.id DESC LIMIT 20")->fetchAll();$audits=$pdo->query("SELECT al.*,u.full_name FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id ORDER BY al.id DESC LIMIT 10")->fetchAll();include 'partials/header.php'; ?>
<div class="grid"><div class="s-4"><div class="card stat"><span class="mark">Q</span><div class="label">Kunjungan hari ini</div><div class="num"><?=$today?></div><div class="meta">Seluruh unit registrasi</div></div></div><div class="s-4"><div class="card stat"><span class="mark">…</span><div class="label">Dalam alur layanan</div><div class="num"><?=$waiting?></div><div class="meta">Terdaftar, menunggu, dipanggil</div></div></div><div class="s-4"><div class="card stat"><span class="mark">✓</span><div class="label">Selesai</div><div class="num"><?=$completed?></div><div class="meta">Kunjungan selesai diproses</div></div></div></div>
<div class="grid mt"><div class="s-5"><div class="card"><div class="card-title"><div><h2>Aktivitas per unit</h2><p>Distribusi kunjungan hari ini.</p></div></div><?php foreach($units as $u): ?><div class="mini-row"><span><?=e($u['name'])?></span><b><?=e($u['total'])?></b></div><?php endforeach; ?></div></div><div class="s-7"><div class="card"><div class="card-title"><div><h2>Antrean registrasi hari ini</h2><p>Pemantauan transaksi yang baru masuk.</p></div></div><div class="table-wrap"><table><tr><th>Antrean</th><th>Pasien</th><th>Unit</th><th>Dokter</th><th>Status</th></tr><?php foreach($visits as $v): ?><tr><td class="queue"><?=e($v['queue_no'])?></td><td><b><?=e($v['name'])?></b><div class="muted"><?=e($v['medical_record_no'])?></div></td><td><?=e($v['clinic'])?></td><td><?=e($v['doctor']?:'—')?></td><td><span class="badge <?=in_array($v['status'],['Terdaftar','Menunggu'],true)?'amber':($v['status']==='Selesai'?'green':'blue')?>"><?=e($v['status'])?></span></td></tr><?php endforeach; ?></table><?php if(!$visits): ?><div class="empty">Belum ada transaksi hari ini.</div><?php endif; ?></div></div></div></div>
<div class="card mt"><div class="card-title"><div><h2>Aktivitas administrasi</h2><p>Riwayat perubahan penting pada modul registrasi.</p></div></div><div class="table-wrap"><table><tr><th>Waktu</th><th>Petugas</th><th>Aktivitas</th><th>Detail</th></tr><?php foreach($audits as $a): ?><tr><td><?=e(date('d/m/Y H:i',strtotime($a['created_at'])))?></td><td><?=e($a['full_name']?:'System')?></td><td><?=e(str_replace('_',' ',ucwords(strtolower($a['action']))))?></td><td><?=e($a['details'])?></td></tr><?php endforeach; ?></table></div></div>
<?php include 'partials/footer.php'; ?>
